mapper.select:
SELECT ifnull(count(*), 0) FROM( SELECT DISTINCT fa.* FROM `mp_flow_actuator` fa LEFT JOIN mp_flow_task_task ftt ON fa.id = ftt.actuator_id LEFT JOIN mp.mp_scene_scene ss ON ftt.scene_id = ss.id where 1=1
and ss.name = #{instanceId}
)temp

SELECT DISTINCT fa.id, fa.title, fa.ip, fa.status, fa.create_time, ss.name as scene_name, fa.network_id as target_subnet FROM `mp_flow_actuator` fa LEFT JOIN mp_flow_task_task ftt ON fa.id = ftt.actuator_id LEFT JOIN mp.mp_scene_scene ss ON ftt.scene_id = ss.id where 1=1
and ss.name = #{instanceId}
group by fa.id ORDER BY fa.create_time desc, fa.title desc limit #{pageFrontIndex}, #{perPage}
